```javascript
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, texture, normalMap } from 'three/tsl';
import { gsap } from 'gsap';

function hexToVec3(hex) {
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  return vec3(r, g, b);
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.userData.cleanup = () => {
    gsap.killTweensOf([group, captionGroup, plateGroup]);
    if (plateMaterial) plateMaterial.dispose();
    if (plateGeometry) plateGeometry.dispose();
    if (rimLightGeometry) rimLightGeometry.dispose();
    if (rimLightMaterial) rimLightMaterial.dispose();
    if (scrimGeometry) scrimGeometry.dispose();
    if (scrimMaterial) scrimMaterial.dispose();
    if (textObjects) textObjects.forEach(obj => obj.traverse(n => {
      if (n.geometry) n.geometry.dispose();
      if (n.material) n.material.dispose();
    }));
    primitiveResult?.cleanup?.();
  };

  // Parse text content with fallbacks
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMap = {};
  for (const item of textItems) {
    textMap[item.role] = item.text;
  }
  const kicker = textMap['kicker'] || 'NOVA ATELIER / GENEVA';
  const headline = textMap['headline'] || 'Time, Machined.';
  const body = textMap['body'] || 'Every case begins as a single billet of 904L steel.';
  const caption = textMap['caption'] || 'CALIBRE NA-01 / 72 HOUR RESERVE';

  // Colors from spec
  const colors = config.intent?.visualSpec?.colors || {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // === BACKDROP STAGE ===
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    colorNode: hexToVec3(colors.background),
  });
  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = -1;
  group.add(backdrop);

  // === PARALLAX PHOTO PLATE (tessellated with displacement) ===
  const plateGroup = new THREE.Group();
  plateGroup.position.z = 0;
  group.add(plateGroup);

  const plateGeometry = new THREE.PlaneGeometry(4.0, 2.5, 64, 64);
  let plateMaterial;
  let displacementMap;
  let colorMap;

  // Load both textures in parallel
  const loadPromises = [];

  const colorMapPromise = config.imageUrl 
    ? ctx.textureLoader.loadTexture(config.imageUrl).then(tex => { colorMap = tex; })
    : Promise.resolve();
  loadPromises.push(colorMapPromise);

  const dispMapPromise = config.depthMapUrl
    ? ctx.textureLoader.loadTexture(config.depthMapUrl).then(tex => { displacementMap = tex; })
    : Promise.resolve();
  loadPromises.push(dispMapPromise);

  // Once textures load, create material with TSL
  Promise.all(loadPromises).then(() => {
    if (plateMaterial) plateMaterial.dispose();

    const uvNode = uv();

    // Filmic grade processing: blacks lifted, highlights shouldered, midtone contrast +12%, desaturation -8% (preserve red)
    const colorSample = colorMap ? texture(colorMap, uvNode) : vec3(1.0, 0.165, 0.22);

    // Lift blacks: mix toward #0d0d12
    const blackLift = mix(vec3(0.05, 0.05, 0.07), colorSample, smoothstep(0, 0.2, colorSample.x));

    // Shoulder highlights toward #e8ecf2
    const shouldered = mix(blackLift, vec3(0.91, 0.93, 0.95), smoothstep(0.8, 1.0, colorSample.x));

    // Midtone contrast: enhance the 0.3-0.7 range by ~12%
    const contrastBoost = mix(shouldered, shouldered.mul(1.12), smoothstep(0.3, 0.7, shouldered.x));

    // Desaturation -8% but preserve red: reduce sat on G,B channels
    const desaturated = vec3(
      contrastBoost.x,
      contrastBoost.y.mul(0.92),
      contrastBoost.z.mul(0.92)
    );

    const displacementNode = displacementMap 
      ? texture(displacementMap, uvNode).x.mul(0.18)
      : uniform(0);

    plateMaterial = new MeshStandardNodeMaterial({
      colorNode: desaturated,
      metalness: 0.0,
      roughness: 0.8,
      emissive: vec3(0, 0, 0),
      emissiveIntensity: 0.0,
    });

    // Apply displacement to geometry
    plateGeometry.attributes.position.needsUpdate = true;
    const positionAttribute = plateGeometry.getAttribute('position');
    const originalPositions = positionAttribute.array.slice();

    if (displacementMap) {
      displacementMap.source.data.addEventListener?.('load', updateDisplacement, { once: true });
      updateDisplacement();
    }

    function updateDisplacement() {
      if (!displacementMap) return;
      const canvas = displacementMap.source.data;
      if (canvas.width === 0 || canvas.height === 0) return;

      const ctx2d = canvas.getContext('2d');
      const imageData = ctx2d.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      for (let i = 0; i < positionAttribute.count; i++) {
        const x = positionAttribute.getX(i);
        const y = positionAttribute.getY(i);

        const u = (x / 4.0 + 0.5) * (canvas.width - 1);
        const v = (1 - (y / 2.5 + 0.5)) * (canvas.height - 1);

        const pixelIdx = (Math.floor(v) * canvas.width + Math.floor(u)) * 4;
        const depth = data[pixelIdx] / 255.0;

        const z = originalPositions[i * 3 + 2] + depth * 0.18;
        positionAttribute.setZ(i, z);
      }
      positionAttribute.needsUpdate = true;
    }

    const plate = new THREE.Mesh(plateGeometry, plateMaterial);
    plate.castShadow = true;
    plate.receiveShadow = true;
    plate.renderOrder = 0;

    // Entrance animation: opacity 0->1 over 500ms cubic-bezier(0.25,0.46,0.45,0.94)
    plate.material.transparent = true;
    plate.material.opacity = 0;
    gsap.to(plate.material, {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    });

    plateGroup.add(plate);
  });

  // === RIM LIGHT (silhouette separation) ===
  const rimLightGeometry = new THREE.PlaneGeometry(4.0, 2.5, 2, 2);
  const rimLightMaterial = new MeshStandardNodeMaterial({
    emissive: vec3(0.3, 0.3, 0.3),
    emissiveIntensity: 0.1,
    metalness: 0.0,
    roughness: 1.0,
    transparent: true,
    opacity: 0,
  });
  const rimLight = new THREE.Mesh(rimLightGeometry, rimLightMaterial);
  rimLight.position.z = 0.01;
  rimLight.renderOrder = 1;
  plateGroup.add(rimLight);

  // === SCRIM GRADIENT (bottom to seat caption) ===
  const scrimGeometry = new THREE.PlaneGeometry(4.0, 2.5);
  const scrimUv = uv();
  const scrimColor = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.043, 0.043, 0.063),
    smoothstep(0.45, 1.0, scrimUv.y)
  );
  const scrimMaterial = new MeshStandardNodeMaterial({
    colorNode: scrimColor,
    metalness: 0.0,
    roughness: 1.0,
    transparent: true,
  });
  const scrim = new THREE.Mesh(scrimGeometry, scrimMaterial);
  scrim.position.z = 0.02;
  scrim.renderOrder = 2;
  plateGroup.add(scrim);

  // === CAPTION BLOCK (bottom-left, 0.5-unit padding) ===
  const captionGroup = new THREE.Group();
  captionGroup.position.set(-1.45, -1.05, 0.05);
  captionGroup.renderOrder = 3;

  // Entrance: rise-in y +0.4 -> 0 over 700ms, delay 120ms
  captionGroup.position.y += 0.4;
  setTimeout(() => {
    gsap.to(captionGroup.position, {
      y: -1.05,
      duration: 0.7,
      ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
    });
  }, 120);

  const textObjects = [];

  // Kicker: JetBrains Mono 9px 700 #e8ecf2
  const kickerText = ctx.fontAtlas.createText(kicker, {
    fontSize: 9,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 0.12 * 9 / 100,
  });
  kickerText.position.y = 0;
  captionGroup.add(kickerText);
  textObjects.push(kickerText);

  // Headline: Lora 34px 600 #e8ecf2
  const headlineText = ctx.fontAtlas.createText(headline, {
    fontSize: 34,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: -0.01 * 34 / 100,
  });
  headlineText.position.y = -0.25;
  captionGroup.add(headlineText);
  textObjects.push(headlineText);

  // Accent hairline bar: #ff2a38 emissive 1.8, 0.75w x 0.02h
  const barGeometry = new THREE.PlaneGeometry(0.75, 0.02);
  const barMaterial = new MeshStandardNodeMaterial({
    emissive: vec3(1.0, 0.165, 0.22),
    emissiveIntensity: 1.8,
    metalness: 0.0,
    roughness: 0.6,
  });
  const bar = new THREE.Mesh(barGeometry, barMaterial);
  bar.position.y = -0.5;
  bar.position.z = 0.01;
  captionGroup.add(bar);

  // Body: JetBrains Mono 13px 400 #e8ecf2
  const bodyText = ctx.fontAtlas.createText(body, {
    fontSize: 13,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 150,
    letterSpacingPx: 0,
  });
  bodyText.position.y = -0.75;
  captionGroup.add(bodyText);
  textObjects.push(bodyText);

  // Caption line: JetBrains Mono 9px 400 #e8ecf2
  const captionText = ctx.fontAtlas.createText(caption, {
    fontSize: 9,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 0.12 * 9 / 100,
  });
  captionText.position.y = -1.2;
  captionGroup.add(captionText);
  textObjects.push(captionText);

  group.add(captionGroup);

  // === APPLY PARALLAX-SCROLL PRIMITIVE ===
  let primitiveResult = null;
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name === 'parallax-scroll') {
        primitiveResult = ctx.primitives['parallax-scroll'](group, prim.params || { intensity: 0.35 });
      }
    }
  } else {
    primitiveResult = ctx.primitives['parallax-scroll'](group, { intensity: 0.35 });
  }

  return group;
}
